svg.script:

const urlTexto = 'https://raw.githubusercontent.com/richardiman/recursoejemplo/main/contenido.txt';

// Añadimos un parámetro de tiempo a la URL para evitar que el navegador guarde el texto viejo en caché
fetch(urlTexto + '?t=' + new Date().getTime())
  .then(response => {
    if (!response.ok) throw new Error('Error al conectar con GitHub');
    return response.text();
  })
  .then(data => {
    // Dividimos el texto por cada salto de línea (\n)
    const lineas = data.split('\n');

    // Asignamos cada línea a su respectivo elemento en el diseño
    if(lineas[0]) document.getElementById('txtCurso').textContent = lineas[0].trim();
    if(lineas[1]) document.getElementById('txtGrupo').textContent = lineas[1].trim();
    if(lineas[2]) document.getElementById('txtDocente').textContent = 'Docente: ' + lineas[2].trim();
    if(lineas[3]) document.getElementById('txtCorreo').textContent = lineas[3].trim();
  })
  .catch(error => {
    console.error('Error al cargar:', error);
  });
